package com.wynnvp.wynncraftvp.sound.physics;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Evenly spread ray directions, generated by the golden-spiral construction.
 *
 * <p>Deliberately deterministic: identical geometry has to produce an identical result, or the
 * re-evaluation every ten ticks feeds noise into {@link AcousticSmoother} and the reverb audibly
 * wobbles. That is also why no direction set is ever randomly rotated.
 */
public final class FibonacciSphere {
    private static final double GOLDEN_ANGLE = Math.PI * (3.0 - Math.sqrt(5.0));
    private static final double[] EMPTY = new double[0];
    private static final Map<Integer, double[]> CACHE = new ConcurrentHashMap<>();

    private FibonacciSphere() {
        throw new UnsupportedOperationException("Utility class");
    }

    /**
     * {@code count} unit vectors, flattened as x, y, z triples.
     *
     * <p>The returned array is shared and cached — treat it as read-only.
     */
    public static double[] directions(int count) {
        if (count <= 0) {
            return EMPTY;
        }
        return CACHE.computeIfAbsent(count, FibonacciSphere::build);
    }

    private static double[] build(int count) {
        double[] out = new double[count * 3];
        for (int i = 0; i < count; i++) {
            double y = 1.0 - 2.0 * (i + 0.5) / count;
            double radius = Math.sqrt(Math.max(0.0, 1.0 - y * y));
            double phi = GOLDEN_ANGLE * i;
            out[i * 3] = radius * Math.cos(phi);
            out[i * 3 + 1] = y;
            out[i * 3 + 2] = radius * Math.sin(phi);
        }
        return out;
    }
}
